// ── Deterministic mock-data generator for full timeline ──
export interface DataPoint {
  date: string;
  displayDate: string;
  value: number;
}

const MONTH_NAMES = ['Янв','Фев','Мар','Апр','Май','Июн','Июл','Авг','Сен','Окт','Ноя','Дек'];

function mulberry32(a: number) {
  return function() {
    let t = a += 0x6D2B79F5;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  }
}

function generateFullHistory(): {
  registrations: DataPoint[];
  visits: DataPoint[];
  activeUsers: DataPoint[];
} {
  const start = new Date(2024, 0, 1);
  const end = new Date(2026, 5, 1); // June 1, 2026
  
  const regs: DataPoint[] = [];
  const vis: DataPoint[] = [];
  const act: DataPoint[] = [];
  
  const rand = mulberry32(888123); // deterministic seed to avoid React hydration mismatch
  
  let current = new Date(start);
  let index = 0;
  
  while (current <= end) {
    const year = current.getFullYear();
    const month = current.getMonth();
    const date = current.getDate();
    
    const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(date).padStart(2, '0')}`;
    const displayDate = `${date} ${MONTH_NAMES[month]} ${String(year).slice(2)}`;
    
    // Steady base growth trend (about 2x over 2.5 years)
    const baseGrowth = 1.0 + (index / 600);
    
    // Weekend drops (Saturday & Sunday are significantly lower, weekdays are steady)
    const dayOfWeek = current.getDay();
    const isWeekend = dayOfWeek === 0 || dayOfWeek === 6;
    const weekendFactor = isWeekend ? (0.55 + rand() * 0.1) : (0.95 + rand() * 0.15);
    
    // A highly organic daily variance without artificial promo spikes
    const dailyVariance = 0.9 + rand() * 0.25;
    
    // Registrations: new registrations added this day (discrete daily count, non-cumulative!)
    const regGrowth = Math.round(25 * baseGrowth * weekendFactor * dailyVariance);
    regs.push({ date: dateStr, displayDate, value: Math.max(1, regGrowth) });
    
    // Visits: clean, realistic day-to-day transitions
    const visitVal = Math.round(900 * baseGrowth * weekendFactor * dailyVariance);
    vis.push({ date: dateStr, displayDate, value: Math.max(10, visitVal) });
    
    // Active users: proportional to visits with standard organic variance
    const activeVal = Math.round(visitVal * (0.65 + rand() * 0.1));
    act.push({ date: dateStr, displayDate, value: Math.max(5, activeVal) });
    
    current.setDate(current.getDate() + 1);
    index++;
  }
  
  return { registrations: regs, visits: vis, activeUsers: act };
}

export const { registrations: allRegData, visits: allVisitsData, activeUsers: allActiveData } = generateFullHistory();

// Hourly breakdown generator for zoom-to-date
export interface HourlyPoint {
  time: string;
  value: number;
}

export function getHourlyData(dateStr: string, totalVal: number, seed: number): HourlyPoint[] {
  const curve = [
    0.10, 0.05, 0.03, 0.02, 0.02, 0.04, // 00:00 - 05:00
    0.15, 0.40, 0.70, 0.85, 0.90, 0.95, // 06:00 - 11:00
    1.00, 0.90, 0.85, 0.95, 1.00, 0.85, // 12:00 - 17:00
    0.80, 0.85, 0.90, 0.75, 0.45, 0.20  // 18:00 - 23:00
  ];
  const sumCurve = curve.reduce((a, b) => a + b, 0);
  
  return Array.from({ length: 24 }, (_, hour) => {
    const timeStr = `${String(hour).padStart(2, '0')}:00`;
    const charCodeSum = dateStr.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0);
    const variance = 1 + Math.sin(charCodeSum + hour + seed) * 0.12;
    const share = (curve[hour] / sumCurve) * variance;
    return {
      time: timeStr,
      value: Math.round(totalVal * share)
    };
  });
}

