const exportToExcel = (data: any[], title: string, isHourly: boolean) => {
  const headers = isHourly ? ['Время', 'Количество'] : ['Дата', 'Количество'];
  const csvRows = [
    headers.join(';'),
    ...data.map(row => {
      const dateVal = isHourly ? row.time : row.date;
      return `${dateVal};${row.value}`;
    })
  ];
  const csvContent = '\uFEFF' + csvRows.join('\n');
  const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.setAttribute('href', url);
  link.setAttribute('download', `${title}_export.csv`);
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
};

interface DateRangePickerProps {
  startDate: string;
  endDate: string;
  minDate: string;
  maxDate: string;
  onChange: (start: string, end: string) => void;
  onReset?: () => void;
  isOpen: boolean;
  setIsOpen: (open: boolean) => void;
  placeholder?: string;
  isHeader?: boolean;
}

function DateRangePicker({
  startDate,
  endDate,
  minDate,
  maxDate,
  onChange,
  onReset,
  isOpen,
  setIsOpen,
  placeholder,
  isHeader,
}: DateRangePickerProps) {
  const [tempStart, setTempStart] = useState(startDate);
  const [tempEnd, setTempEnd] = useState(endDate);
  const [currentMonth, setCurrentMonth] = useState(() => new Date(endDate || new Date()));

  React.useEffect(() => {
    setTempStart(startDate);
    setTempEnd(endDate);
    if (endDate) {
      setCurrentMonth(new Date(endDate));
    }
  }, [startDate, endDate]);

  const nextMonth = () => {
    setCurrentMonth(prev => new Date(prev.getFullYear(), prev.getMonth() + 1, 1));
  };
  const prevMonth = () => {
    setCurrentMonth(prev => new Date(prev.getFullYear(), prev.getMonth() - 1, 1));
  };

  const formatDateRu = (dateStr: string) => {
    if (!dateStr) return '';
    const parts = dateStr.split('-');
    if (parts.length !== 3) return dateStr;
    const year = parts[0];
    const month = MONTH_NAMES[parseInt(parts[1], 10) - 1];
    const day = parseInt(parts[2], 10);
    return `${day} ${month} ${year.slice(2)}`;
  };

  const year = currentMonth.getFullYear();
  const month = currentMonth.getMonth();
  
  const firstDay = new Date(year, month, 1);
  let startDayOfWeek = firstDay.getDay() - 1;
  if (startDayOfWeek === -1) startDayOfWeek = 6;
  
  const totalDays = new Date(year, month + 1, 0).getDate();
  
  const days: (Date | null)[] = [];
  for (let i = 0; i < startDayOfWeek; i++) {
    days.push(null);
  }
  for (let d = 1; d <= totalDays; d++) {
    days.push(new Date(year, month, d));
  }

  const handleDayClick = (date: Date) => {
    const yStr = date.getFullYear();
    const mStr = String(date.getMonth() + 1).padStart(2, '0');
    const dStr = String(date.getDate()).padStart(2, '0');
    const clickedStr = `${yStr}-${mStr}-${dStr}`;
    
    if (!tempStart || (tempStart && tempEnd)) {
      setTempStart(clickedStr);
      setTempEnd('');
    } else {
      if (clickedStr < tempStart) {
        setTempEnd(tempStart);
        setTempStart(clickedStr);
      } else {
        setTempEnd(clickedStr);
      }
    }
  };

  const handleTempStartChange = (val: string) => {
    setTempStart(val);
    if (val && tempEnd && val > tempEnd) {
      setTempEnd('');
    }
  };
  
  const handleTempEndChange = (val: string) => {
    setTempEnd(val);
    if (val && tempStart && val < tempStart) {
      setTempStart(val);
      setTempEnd('');
    }
  };

  const RU_MONTHS = [
    'Январь', 'Февраль', 'Март', 'Апрель', 'Май', 'Июнь', 
    'Июль', 'Август', 'Сентябрь', 'Октябрь', 'Ноябрь', 'Декабрь'
  ];

  return (
    <div className="relative">
      <button 
        onClick={() => setIsOpen(!isOpen)} 
        className={isHeader 
          ? "h-9 px-4 text-[13px] font-semibold bg-white border border-neutral-200 rounded-lg text-neutral-700 hover:border-neutral-300 transition-colors shadow-sm flex items-center gap-2"
          : "flex items-center gap-2 px-3 py-1.5 bg-white border border-neutral-200 rounded-lg text-[11px] font-bold text-neutral-600 hover:border-neutral-300 transition-colors shadow-sm"
        }
        type="button"
      >
        <Calendar className="w-3.5 h-3.5 text-neutral-400" />
        <span>{startDate && endDate ? `${formatDateRu(startDate)} - ${formatDateRu(endDate)}` : (placeholder || "Выбрать диапазон")}</span>
        <ChevronDown className="w-3 h-3 text-neutral-400" />
      </button>

      {isOpen && (
        <>
          <div className="fixed inset-0 z-[190]" onClick={() => setIsOpen(false)} />
          <div className="absolute right-0 mt-2 w-[270px] bg-white border border-neutral-200 rounded-xl shadow-xl z-[200] p-4 animate-in fade-in slide-in-from-top-2 duration-150">
            <div className="flex items-center gap-2 mb-3 pb-3 border-b border-neutral-100">
              <div className="flex flex-col gap-0.5 flex-1">
                <span className="text-[9px] text-neutral-400 font-bold uppercase">От</span>
                <input 
                  type="date" 
                  value={tempStart} 
                  min={minDate} 
                  max={maxDate} 
                  onChange={(e) => handleTempStartChange(e.target.value)}
                  className="w-full px-1.5 py-1 text-[10px] font-bold text-neutral-700 border border-neutral-200 rounded-md focus:outline-none focus:border-neutral-400 bg-neutral-50"
                />
              </div>
              <div className="flex flex-col gap-0.5 flex-1">
                <span className="text-[9px] text-neutral-400 font-bold uppercase">До</span>
                <input 
                  type="date" 
                  value={tempEnd} 
                  min={minDate} 
                  max={maxDate} 
                  onChange={(e) => handleTempEndChange(e.target.value)}
                  className="w-full px-1.5 py-1 text-[10px] font-bold text-neutral-700 border border-neutral-200 rounded-md focus:outline-none focus:border-neutral-400 bg-neutral-50"
                />
              </div>
            </div>

            <div className="flex items-center justify-between mb-2 px-1">
              <button onClick={prevMonth} className="p-1 rounded hover:bg-neutral-100 text-neutral-500" type="button">
                <ChevronLeft className="w-3.5 h-3.5" />
              </button>
              <span className="text-[11px] font-bold text-neutral-700">
                {RU_MONTHS[month]} {year}
              </span>
              <button onClick={nextMonth} className="p-1 rounded hover:bg-neutral-100 text-neutral-500" type="button">
                <ChevronRight className="w-3.5 h-3.5" />
              </button>
            </div>

            <div className="grid grid-cols-7 gap-0.5 text-center mb-3">
              {['Пн', 'Вт', 'Ср', 'Чт', 'Пт', 'Сб', 'Вс'].map(day => (
                <span key={day} className="text-[9px] font-bold text-neutral-400 py-1">{day}</span>
              ))}
              {days.map((date, idx) => {
                if (!date) return <div key={`empty-${idx}`} className="w-7 h-7" />;
                
                const yStr = date.getFullYear();
                const mStr = String(date.getMonth() + 1).padStart(2, '0');
                const dStr = String(date.getDate()).padStart(2, '0');
                const dateStr = `${yStr}-${mStr}-${dStr}`;
                
                const isSelectedStart = tempStart === dateStr;
                const isSelectedEnd = tempEnd === dateStr;
                const isInRange = tempStart && tempEnd && dateStr > tempStart && dateStr < tempEnd;
                const isDisabled = dateStr < minDate || dateStr > maxDate;
                
                let btnClass = "w-7 h-7 text-[10px] font-semibold flex items-center justify-center transition-all ";
                if (isDisabled) {
                  btnClass += "text-neutral-300 pointer-events-none";
                } else if (isSelectedStart || isSelectedEnd) {
                  btnClass += "bg-neutral-900 text-white rounded-lg shadow-sm font-bold scale-105 z-10";
                } else if (isInRange) {
                  btnClass += "bg-neutral-100 text-neutral-900 font-bold rounded-none";
                } else {
                  btnClass += "text-neutral-700 hover:bg-neutral-100 rounded-lg";
                }
                
                return (
                  <button
                    key={dateStr}
                    onClick={() => handleDayClick(date)}
                    className={btnClass}
                    type="button"
                  >
                    {date.getDate()}
                  </button>
                );
              })}
            </div>

            <div className="flex gap-2">
              {onReset && (
                <button 
                  onClick={() => {
                    setTempStart('');
                    setTempEnd('');
                    onReset();
                    setIsOpen(false);
                  }}
                  className="flex-1 py-1.5 border border-neutral-200 hover:bg-neutral-50 text-neutral-500 rounded-lg text-[11px] font-bold transition-colors shadow-sm bg-white"
                  type="button"
                >
                  Сбросить
                </button>
              )}
              <button 
                onClick={() => {
                  if (tempStart && tempEnd) {
                    onChange(tempStart, tempEnd);
                  } else if (tempStart) {
                    onChange(tempStart, tempStart);
                  }
                  setIsOpen(false);
                }}
                className="flex-1 py-1.5 bg-neutral-900 hover:bg-neutral-800 text-white rounded-lg text-[11px] font-bold transition-colors shadow-sm"
                type="button"
              >
                Применить
              </button>
            </div>
          </div>
        </>
      )}
    </div>
  );
}

interface FilterDropdownProps {
  label: string;
  options: string[];
  selectedValue: string;
  onChange: (val: string) => void;
}

function FilterDropdown({ label, options, selectedValue, onChange }: FilterDropdownProps) {
  const [isOpen, setIsOpen] = useState(false);
  const [search, setSearch] = useState('');

  const filteredOptions = options.filter(opt => 
    opt.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="relative flex-1 min-w-[140px]">
      <button 
        onClick={() => setIsOpen(!isOpen)}
        className="w-full flex items-center justify-between gap-2 px-3 py-2 bg-white border border-neutral-200 rounded-lg text-[13px] font-medium text-neutral-700 hover:border-neutral-300 transition-colors shadow-sm"
        type="button"
      >
        <span className="truncate">{selectedValue || label}</span>
        <ChevronDown className="w-4 h-4 text-neutral-400 shrink-0" />
      </button>
      
      {isOpen && (
        <>
          <div className="fixed inset-0 z-[190]" onClick={() => { setIsOpen(false); setSearch(''); }} />
          <div className="absolute left-0 mt-1 w-full bg-white border border-neutral-200 rounded-xl shadow-lg z-[200] py-1 max-h-72 overflow-y-auto flex flex-col">
            <div className="p-2 border-b border-neutral-100 shrink-0">
              <input
                type="text"
                value={search}
                onChange={e => setSearch(e.target.value)}
                placeholder="Поиск..."
                className="w-full px-2.5 py-1.5 text-xs border border-neutral-200 rounded-md outline-none focus:border-[var(--color-admin-primary-500)]"
              />
            </div>
            <div className="overflow-y-auto flex-1">
              {filteredOptions.map(opt => (
                <button
                  key={opt}
                  onClick={() => {
                    onChange(opt === label ? "" : opt);
                    setIsOpen(false);
                    setSearch('');
                  }}
                  className={`w-full text-left px-3 py-2 text-xs font-semibold hover:bg-neutral-50 transition-colors ${(selectedValue === opt || (!selectedValue && opt === label)) ? "text-[var(--color-admin-primary-600)] bg-[var(--color-admin-primary-50)]" : "text-neutral-700"}`}
                  type="button"
                >
                  {opt}
                </button>
              ))}
              {filteredOptions.length === 0 && (
                <div className="px-3 py-4 text-xs text-neutral-400 text-center">Ничего не найдено</div>
              )}
            </div>
          </div>
        </>
      )}
    </div>
  );
}

